insert into public.case_studies (id, slug, client, title, hero_lines, summary, brief, what_we_did, results, quote, cover, gallery, related, category, sample, published, sort_order) values
  ('sample-brokerage-monthly', 'sample-monthly-content-for-a-brokerage', 'Dubai brokerage (sample)', 'Monthly listing content for a brokerage', array['Monthly content', 'for a brokerage.']::text[], 'Shoot days, reels and long-form walkthroughs on a monthly plan.', 'A growing brokerage needed every new listing photographed and on social media within days, without briefing a different photographer each time.', array['Set up a monthly plan of half and full shoot days across their communities.', 'Photographed each listing and cut a vertical reel and a long-form walkthrough.', 'Delivered everything to one dashboard with a monthly statement.']::text[], '[{"value":"—","label":"Listings shot per month"},{"value":"—","label":"Reels delivered"},{"value":"—","label":"Average turnaround"}]'::jsonb, null, '{"alt":"Placeholder: apartment interior from a listing shoot","placeholder":"interior"}'::jsonb, '[{"alt":"Placeholder: living room","placeholder":"interior"},{"alt":"Placeholder: kitchen","placeholder":"kitchen"},{"alt":"Placeholder: penthouse at night","placeholder":"night"}]'::jsonb, array['item-1', 'item-2', 'item-5']::text[], 'property', true, true, 1)
