  ('twilight', 'Twilight', 'Virtual twilight', 'A daytime exterior turned into a dusk shot with warm windows and a glowing pool. The listing photo that gets the click.', '{"alt":"Villa exterior in daylight, before editing","placeholder":"villa"}'::jsonb, '{"alt":"Same villa converted to twilight, after editing","placeholder":"villa-dusk"}'::jsonb, null, false, true, true, 2),
