insert into public.reviews (id, name, role, company, rating, text, source, link, placements, sample, published, sort_order) values
  ('sample-1', null, 'Leasing manager', 'Dubai brokerage', 5, 'We send the address, they handle the rest. Photos are back the next morning and the listing goes live the same day.', 'google', null, array['home']::text[], true, true, 1),
  ('sample-2', null, 'Marketing lead', 'Developer', 5, 'Twenty reels a month without us thinking about it. The content plan alone saved our marketing team hours.', 'google', null, array['home']::text[], true, true, 2),
  ('sample-3', null, 'Agent', 'Holiday homes', 5, 'Clear prices, no chasing files. Everything is in the dashboard with the invoice.', 'google', null, array['home']::text[], true, true, 3)
insert into public.faqs (id, page, question, answer, draft, published, sort_order) values
  ('home-1', 'home', 'Where do you work?', 'We shoot across the UAE, based in Dubai. Editing and AI avatars are fully remote, so we work with clients anywhere.', true, true, 1),
  ('home-2', 'home', 'How fast is delivery?', 'Property photos in 24 hours. Reels in 24–48 hours. Monthly packages follow an agreed content calendar.', true, true, 2),
  ('home-3', 'home', 'How does pricing work?', 'Every service page shows starting prices. The final quote is confirmed in chat or on a short call, before you pay anything.', true, true, 3),
  ('home-4', 'home', 'How do I start?', 'Send a request or WhatsApp us. We reply within 15 minutes during working hours.', true, true, 4),
  ('production-5', 'production', 'How many revisions do I get?', 'Two rounds of revisions per edit are included. Changes to the brief after shooting are quoted separately.', true, true, 5),
  ('production-6', 'production', 'What if I don''t use all my shoot days?', 'Unused shoot days can move to the next month once. We''ll remind you mid-month so nothing is wasted.', true, true, 6),
  ('production-7', 'production', 'Who owns the footage?', 'You do. Final edits and raw footage from your shoots are yours to use anywhere.', true, true, 7),
  ('production-8', 'production', 'Can I change package mid-contract?', 'Yes. Your package can grow with your listings from any month.', true, true, 8),
  ('property-shoots-9', 'property-shoots', 'How should I prepare the property?', 'Lights on, blinds open, surfaces clear, personal items away. We send a 5-point checklist when you book.', true, true, 9),
  ('property-shoots-10', 'property-shoots', 'Can I reschedule?', 'Yes, free up to 24 hours before the shoot.', true, true, 10),
  ('property-shoots-11', 'property-shoots', 'Which areas do you cover?', 'All of Dubai. Other emirates on request.', true, true, 11),
  ('property-shoots-12', 'property-shoots', 'What if the weather is bad?', 'We move exterior shots to a clear day at no cost, or replace the sky in editing.', true, true, 12),
  ('post-production-13', 'post-production', 'Can you match our current editing style?', 'Yes. Send 5–10 finished photos you like. We build a preset and a written style guide before your first batch.', true, true, 13),
  ('post-production-14', 'post-production', 'What file formats do you accept?', 'RAW brackets (CR3, NEF, ARW, DNG), JPEG, and video in any common format. Deliverables in the size and naming you need.', true, true, 14),
  ('post-production-15', 'post-production', 'How do payments work?', 'We invoice monthly after a custom quote.', true, true, 15),
  ('post-production-16', 'post-production', 'Is the free test really free?', 'Yes. After a 15-minute call we edit one listing (up to 10 photos) or one reel, free, so you can judge the quality.', true, true, 16),
  ('ai-avatars-17', 'ai-avatars', 'Will people know it''s AI?', 'Most won''t spot it. We still label AI content where platforms require it, such as Meta and TikTok, and we recommend being open about it.', true, true, 17),
  ('ai-avatars-18', 'ai-avatars', 'Who owns the avatar?', 'You do. The avatar is built for your brand and isn''t reused for anyone else.', true, true, 18),
  ('ai-avatars-19', 'ai-avatars', 'Can it speak Arabic?', 'Yes. English and Arabic are supported, and other languages on request.', true, true, 19),
  ('ai-avatars-20', 'ai-avatars', 'Can it look like me?', 'Yes, with your consent and a short photo session we can build an avatar based on you.', true, true, 20)
