insert into public.site_settings (key, value) values
  ('site', '{"company":"Milkywayy LLC","licence":"Sharjah Media City","addressLine":"Dubai, UAE","whatsapp":{"number":"971507263306","display":"+971 50 726 3306"},"email":"hello@milkywayy.com","instagram":{"handle":"@milkywayy_com","url":"https://www.instagram.com/milkywayy_com"},"linkedin":{"handle":"milkywayy-com","url":"https://www.linkedin.com/company/milkywayy-com"},"googleRating":{"value":5,"count":null},"founder":{"name":"Akash Praseed","role":"Founder, Milkywayy","quote":"After years of creating content, we know where production slows down: the follow-ups, the revisions, the back-and-forth. So we''re building systems that take them out. You book, we shoot, you download.","photo":{"src":"/founder.webp","alt":"Akash Praseed, founder of Milkywayy","focus":"55% 15%"}},"showreel":{"alt":"Showreel placeholder: Dubai skyline at dusk","placeholder":"dusk","duration":"0:45"},"booking":{"slots":["Morning","Afternoon","Evening"],"closedWeekdays":[0],"windowDays":60,"multiPropertyNote":"Shooting more than one property on the same day or in the same area? We''ll send you a better price for the whole booking in the same chat."},"proofStripPages":["home","production"],"footerLine":"A Dubai content studio. Production in the UAE, editing and AI presenters worldwide."}'::jsonb),
  ('avatar_hero', '{"name":"Adam","poster":{"alt":"Placeholder: Adam, AI presenter, in a bright loft","placeholder":"adam","bright":true},"timecode":"REC 00:00:07:12","captionLead":"Dubai rents are up again this quarter. Here''s what that means","captionHighlight":"for buyers.","revealTitle":"100% AI","revealText":"Face, voice and gestures generated · edited by Milkywayy","proofLead":"Clients shown Adam","proofHighlight":"didn''t spot he was AI","sample":true}'::jsonb)
